// Atomic "get and increment" with Lua
const script = `
  local val = redis.call("GET", KEYS[1])
  if not val then val = 0 end
  redis.call("SET", KEYS[1], tonumber(val) + ARGV[1])
  return tonumber(val) + ARGV[1]
`;

const result = await redis.eval(script, 1, "counter:page1", 1);

// Cache the script SHA for efficiency
const sha = await redis.scriptLoad(script);
const val = await redis.evalsha(sha, 1, "counter:page1", 1);
